export const BITMASK_DEFS = "// Phase 0: Voxel Bitmask Schema — shared by all compute shaders.\n//\n// 32-bit voxel state encoding:\n//   Bits  0-7:  Material ID   (256 materials)\n//   Bits  8-15: Thermal energy (0-255)\n//   Bits 16-19: Kinetic X      (-8 to +7, 4-bit two's complement)\n//   Bits 20-23: Kinetic Y      (-8 to +7, 4-bit two's complement)\n//   Bits 24-27: Phase state    (16 substates)\n//   Bits 28-31: Flags          (burning, conducting, pressurized, player-owned)\n\n// ── Bit layout constants ───────────────────────────────────────────\n\nconst MATERIAL_SHIFT: u32 = 0u;\nconst MATERIAL_MASK:  u32 = 0xFFu;\n\nconst THERMAL_SHIFT:  u32 = 8u;\nconst THERMAL_MASK:   u32 = 0xFFu;\n\nconst KINETIC_X_SHIFT: u32 = 16u;\nconst KINETIC_X_MASK:  u32 = 0xFu;\n\nconst KINETIC_Y_SHIFT: u32 = 20u;\nconst KINETIC_Y_MASK:  u32 = 0xFu;\n\nconst PHASE_SHIFT:    u32 = 24u;\nconst PHASE_MASK:     u32 = 0xFu;\n\nconst FLAGS_SHIFT:    u32 = 28u;\nconst FLAGS_MASK:     u32 = 0xFu;\n\n// ── Material IDs ───────────────────────────────────────────────────\n\nconst MAT_AIR:    u32 = 0u;\nconst MAT_STONE:  u32 = 1u;\nconst MAT_WATER:  u32 = 2u;\nconst MAT_SAND:   u32 = 3u;\nconst MAT_FIRE:   u32 = 4u;\nconst MAT_METAL:  u32 = 5u;\nconst MAT_OIL:    u32 = 6u;\nconst MAT_WOOD:   u32 = 7u;\nconst MAT_ICE:    u32 = 8u;\nconst MAT_STEAM:  u32 = 9u;\nconst MAT_LAVA:   u32 = 10u;\nconst MAT_GLASS:  u32 = 11u;\nconst MAT_PLAYER: u32 = 12u;\nconst MAT_ASH:    u32 = 13u;\nconst MAT_SMOKE:  u32 = 14u;\n\n// ── Phase states ───────────────────────────────────────────────────\n\nconst PHASE_SOLID:       u32 = 0u;\nconst PHASE_POWDER:      u32 = 1u;\nconst PHASE_LIQUID:      u32 = 2u;\nconst PHASE_VISCOUS:     u32 = 3u;\nconst PHASE_GAS:         u32 = 4u;\nconst PHASE_PLASMA:      u32 = 5u;\nconst PHASE_FROZEN:      u32 = 6u;\nconst PHASE_MOLTEN:      u32 = 7u;\nconst PHASE_BURNING:     u32 = 8u;\nconst PHASE_CONDENSING:  u32 = 9u;\nconst PHASE_EVAPORATING: u32 = 10u;\nconst PHASE_SUBLIMATING: u32 = 11u;\n\n// ── Flags ──────────────────────────────────────────────────────────\n\nconst FLAG_BURNING:      u32 = 0x1u;\nconst FLAG_CONDUCTING:   u32 = 0x2u;\nconst FLAG_PRESSURIZED:  u32 = 0x4u;\nconst FLAG_PLAYER_OWNED: u32 = 0x8u;\n\n// ── Unpacked voxel struct ──────────────────────────────────────────\n\nstruct VoxelState {\n    material:  u32,\n    thermal:   u32,\n    kinetic_x: i32,   // -8 to +7\n    kinetic_y: i32,   // -8 to +7\n    phase:     u32,\n    flags:     u32,\n}\n\n// ── Grid dimensions (set per dispatch) ─────────────────────────────\n\noverride GRID_WIDTH:  u32 = 256u;\noverride GRID_HEIGHT: u32 = 256u;\n";
export const LOCKED_1A = "// Seed 2: Branchless optimized pack/unpack\n// Uses bitwise tricks to avoid branching for sign extension.\n\nfn pack_voxel(mat: u32, thermal: u32, kx: i32, ky: i32, phase: u32, flags: u32) -> u32 {\n    // Single expression pack — compiler can fuse these\n    return ((mat & MATERIAL_MASK) << MATERIAL_SHIFT)\n         | ((thermal & THERMAL_MASK) << THERMAL_SHIFT)\n         | ((u32(kx) & KINETIC_X_MASK) << KINETIC_X_SHIFT)\n         | ((u32(ky) & KINETIC_Y_MASK) << KINETIC_Y_SHIFT)\n         | ((phase & PHASE_MASK) << PHASE_SHIFT)\n         | ((flags & FLAGS_MASK) << FLAGS_SHIFT);\n}\n\nfn unpack_voxel(packed: u32) -> VoxelState {\n    var state: VoxelState;\n    state.material = (packed >> MATERIAL_SHIFT) & MATERIAL_MASK;\n    state.thermal = (packed >> THERMAL_SHIFT) & THERMAL_MASK;\n\n    // Branchless sign extension: (val ^ 0x8) - 0x8 converts 4-bit unsigned to signed\n    let kx_raw = (packed >> KINETIC_X_SHIFT) & KINETIC_X_MASK;\n    let ky_raw = (packed >> KINETIC_Y_SHIFT) & KINETIC_Y_MASK;\n    state.kinetic_x = i32((kx_raw ^ 0x8u) - 0x8u);\n    state.kinetic_y = i32((ky_raw ^ 0x8u) - 0x8u);\n\n    state.phase = (packed >> PHASE_SHIFT) & PHASE_MASK;\n    state.flags = (packed >> FLAGS_SHIFT) & FLAGS_MASK;\n    return state;\n}\n\nfn exchange_thermal(a: u32, b: u32) -> vec2<u32> {\n    // Branchless thermal exchange with configurable rate\n    let ta = (a >> THERMAL_SHIFT) & THERMAL_MASK;\n    let tb = (b >> THERMAL_SHIFT) & THERMAL_MASK;\n\n    // Arithmetic shift for signed division\n    let diff = i32(ta) - i32(tb);\n    let transfer = diff >> 2;  // Divide by 4 via shift\n\n    let new_ta = u32(max(min(i32(ta) - transfer, 255), 0));\n    let new_tb = u32(max(min(i32(tb) + transfer, 255), 0));\n\n    let clear_mask = ~(THERMAL_MASK << THERMAL_SHIFT);\n    return vec2<u32>(\n        (a & clear_mask) | (new_ta << THERMAL_SHIFT),\n        (b & clear_mask) | (new_tb << THERMAL_SHIFT)\n    );\n}\n\n// ── Compute entry point ────────────────────────────────────────────\n\n\n";
export const GRAVITY_SHADER = "// Conservative vertical matter gravity with phased symmetric density swaps.\n//\n// Movement is limited to disjoint row pairs selected by GRAVITY_PHASE, so a\n// cell can participate in at most one swap per pass and per-material counts are\n// preserved exactly. Gas is handled by separate buoyancy/spread passes.\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE: u32 = 24u;\nconst COLD_DENSITY: u32 = 0u;\noverride GRAVITY_PHASE: u32 = 0u;\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }\n\nfn density_of(mat: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];\n}\n\nfn is_structural(ph: u32) -> bool {\n    return ph == PHASE_SOLID || ph == PHASE_FROZEN;\n}\n\nfn is_vertical_falling_matter(ph: u32) -> bool {\n    return ph == PHASE_SOLID\n        || ph == PHASE_FROZEN\n        || ph == PHASE_POWDER\n        || ph == PHASE_LIQUID\n        || ph == PHASE_VISCOUS\n        || ph == PHASE_MOLTEN;\n}\n\nfn should_swap(upper: u32, lower: u32) -> bool {\n    let upper_mat = get_material(upper);\n    let lower_mat = get_material(lower);\n    let upper_phase = get_phase(upper);\n    let lower_phase = get_phase(lower);\n\n    if (!is_vertical_falling_matter(upper_phase) || is_structural(lower_phase)) {\n        return false;\n    }\n\n    return density_of(upper_mat) > density_of(lower_mat);\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n\n    if (y < GRID_HEIGHT - 1u && ((y & 1u) == GRAVITY_PHASE)) {\n        let below = grid_in[get_idx(x, y + 1u)];\n        if (should_swap(voxel, below)) {\n            grid_out[idx] = below;\n            return;\n        }\n    }\n\n    if (y > 0u && (((y - 1u) & 1u) == GRAVITY_PHASE)) {\n        let above = grid_in[get_idx(x, y - 1u)];\n        if (should_swap(above, voxel)) {\n            grid_out[idx] = above;\n            return;\n        }\n    }\n\n    grid_out[idx] = voxel;\n}\n";
export const DIAGONAL_SHADER = "// Conservative diagonal matter fall.\n//\n// Each pass partitions the grid into disjoint 2x2 cells. One diagonal edge in\n// each block is eligible, chosen by a deterministic hash and MOVE_SALT. This\n// preserves exact per-material counts without atomics.\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE: u32 = 24u;\nconst COLD_DENSITY: u32 = 0u;\noverride MOVE_PHASE: u32 = 0u;\noverride MOVE_SALT: u32 = 0u;\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }\n\nfn density_of(mat: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];\n}\n\nfn is_structural(ph: u32) -> bool {\n    return ph == PHASE_SOLID || ph == PHASE_FROZEN;\n}\n\nfn is_falling_matter(ph: u32) -> bool {\n    return ph == PHASE_POWDER || ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_MOLTEN;\n}\n\nfn can_fall_into(src: u32, dst: u32) -> bool {\n    let src_phase = get_phase(src);\n    let dst_phase = get_phase(dst);\n    if (!is_falling_matter(src_phase) || is_structural(dst_phase)) {\n        return false;\n    }\n    return density_of(get_material(src)) > density_of(get_material(dst));\n}\n\nfn vertical_blocked(x: u32, y: u32, src: u32) -> bool {\n    if (y >= GRID_HEIGHT - 1u) { return true; }\n    let below = grid_in[get_idx(x, y + 1u)];\n    return !can_fall_into(src, below);\n}\n\nfn hash_pair(x: u32, y: u32, salt: u32) -> u32 {\n    var h = x * 374761393u + y * 668265263u + salt * 1442695041u;\n    h = (h ^ (h >> 13u)) * 1274126177u;\n    return h ^ (h >> 16u);\n}\n\nfn should_swap(src_x: u32, src_y: u32, dst_x: u32, dst_y: u32) -> bool {\n    let src = grid_in[get_idx(src_x, src_y)];\n    let dst = grid_in[get_idx(dst_x, dst_y)];\n    return vertical_blocked(src_x, src_y, src) && can_fall_into(src, dst);\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n\n    var upper_y = y;\n    if ((y & 1u) != MOVE_PHASE) {\n        if (y == 0u) {\n            grid_out[idx] = voxel;\n            return;\n        }\n        upper_y = y - 1u;\n    }\n    if (upper_y >= GRID_HEIGHT - 1u) {\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    let pair_left = x - (x & 1u);\n    if (pair_left >= GRID_WIDTH - 1u) {\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    let prefer_right = (hash_pair(pair_left, upper_y, MOVE_SALT) & 1u) == 0u;\n    let src_x = select(pair_left + 1u, pair_left, prefer_right);\n    let dst_x = select(pair_left, pair_left + 1u, prefer_right);\n    let src_y = upper_y;\n    let dst_y = upper_y + 1u;\n    let do_swap = should_swap(src_x, src_y, dst_x, dst_y);\n\n    if (do_swap && x == src_x && y == src_y) {\n        grid_out[idx] = grid_in[get_idx(dst_x, dst_y)];\n        return;\n    }\n    if (do_swap && x == dst_x && y == dst_y) {\n        grid_out[idx] = grid_in[get_idx(src_x, src_y)];\n        return;\n    }\n\n    grid_out[idx] = voxel;\n}\n";
export const LIQUID_SHADER = "// Conservative horizontal liquid spread.\n//\n// Each pass partitions rows into disjoint horizontal pairs. Direction is chosen\n// by a deterministic coordinate hash plus MOVE_SALT to avoid global drift.\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE: u32 = 24u;\nconst COLD_DENSITY: u32 = 0u;\noverride MOVE_PHASE: u32 = 0u;\noverride MOVE_SALT: u32 = 0u;\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }\n\nfn density_of(mat: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];\n}\n\nfn is_structural(ph: u32) -> bool {\n    return ph == PHASE_SOLID || ph == PHASE_FROZEN;\n}\n\nfn is_liquid_like(ph: u32) -> bool {\n    return ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_MOLTEN;\n}\n\nfn is_falling_matter(ph: u32) -> bool {\n    return ph == PHASE_POWDER || ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_MOLTEN;\n}\n\nfn can_fall_into(src: u32, dst: u32) -> bool {\n    let src_phase = get_phase(src);\n    let dst_phase = get_phase(dst);\n    if (!is_falling_matter(src_phase) || is_structural(dst_phase)) {\n        return false;\n    }\n    return density_of(get_material(src)) > density_of(get_material(dst));\n}\n\nfn has_down_or_diagonal_fall(x: u32, y: u32, src: u32) -> bool {\n    if (y >= GRID_HEIGHT - 1u) { return false; }\n    if (can_fall_into(src, grid_in[get_idx(x, y + 1u)])) { return true; }\n    if (x > 0u && can_fall_into(src, grid_in[get_idx(x - 1u, y + 1u)])) { return true; }\n    if (x < GRID_WIDTH - 1u && can_fall_into(src, grid_in[get_idx(x + 1u, y + 1u)])) { return true; }\n    return false;\n}\n\nfn can_spread_into(src: u32, dst: u32) -> bool {\n    if (!is_liquid_like(get_phase(src)) || is_structural(get_phase(dst))) {\n        return false;\n    }\n    let dst_phase = get_phase(dst);\n    if (dst_phase != PHASE_GAS && get_material(dst) != MAT_AIR) {\n        return false;\n    }\n    return density_of(get_material(src)) > density_of(get_material(dst));\n}\n\nfn hash_pair(x: u32, y: u32, salt: u32) -> u32 {\n    var h = x * 374761393u + y * 668265263u + salt * 1442695041u;\n    h = (h ^ (h >> 13u)) * 1274126177u;\n    return h ^ (h >> 16u);\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n\n    var pair_left = x;\n    if (((x + MOVE_PHASE) & 1u) != 0u) {\n        if (x == 0u) {\n            grid_out[idx] = voxel;\n            return;\n        }\n        pair_left = x - 1u;\n    }\n    if (pair_left >= GRID_WIDTH - 1u) {\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    let left = grid_in[get_idx(pair_left, y)];\n    let right = grid_in[get_idx(pair_left + 1u, y)];\n    let left_can = !has_down_or_diagonal_fall(pair_left, y, left) && can_spread_into(left, right);\n    let right_can = !has_down_or_diagonal_fall(pair_left + 1u, y, right) && can_spread_into(right, left);\n    let source_left = select(\n        left_can,\n        (hash_pair(pair_left, y, MOVE_SALT) & 1u) == 0u,\n        left_can && right_can,\n    );\n    let src_x = select(pair_left + 1u, pair_left, source_left);\n    let dst_x = select(pair_left, pair_left + 1u, source_left);\n    let src = select(right, left, source_left);\n    let dst = select(left, right, source_left);\n    let do_swap = left_can || right_can;\n\n    if (do_swap && x == src_x) {\n        grid_out[idx] = dst;\n        return;\n    }\n    if (do_swap && x == dst_x) {\n        grid_out[idx] = src;\n        return;\n    }\n\n    grid_out[idx] = voxel;\n}\n";
export const GAS_BUOYANCY_SHADER = "// Conservative thermal gas buoyancy.\n//\n// Non-air gas/plasma can rise through air or other gas when its thermal\n// buoyancy rank is sufficiently higher than the upper target.\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE: u32 = 24u;\nconst COLD_DENSITY: u32 = 0u;\nconst GAS_RISE_THRESHOLD: i32 = 16;\noverride MOVE_PHASE: u32 = 0u;\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }\nfn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }\n\nfn density_of(mat: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];\n}\n\nfn is_structural(ph: u32) -> bool {\n    return ph == PHASE_SOLID || ph == PHASE_FROZEN;\n}\n\nfn is_gas_like(ph: u32) -> bool {\n    return ph == PHASE_GAS || ph == PHASE_PLASMA;\n}\n\nfn gas_rank(v: u32) -> i32 {\n    return i32(get_thermal(v)) * 2 - i32(density_of(get_material(v)));\n}\n\nfn can_rise(src: u32, dst: u32) -> bool {\n    let src_mat = get_material(src);\n    let src_phase = get_phase(src);\n    let dst_phase = get_phase(dst);\n    if (src_mat == MAT_AIR || !is_gas_like(src_phase) || is_structural(dst_phase)) {\n        return false;\n    }\n    if (get_material(dst) != MAT_AIR && !is_gas_like(dst_phase)) {\n        return false;\n    }\n    return gas_rank(src) > gas_rank(dst) + GAS_RISE_THRESHOLD;\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n\n    if (y < GRID_HEIGHT - 1u && ((y & 1u) == MOVE_PHASE)) {\n        let lower = grid_in[get_idx(x, y + 1u)];\n        if (can_rise(lower, voxel)) {\n            grid_out[idx] = lower;\n            return;\n        }\n    }\n\n    if (y > 0u && (((y - 1u) & 1u) == MOVE_PHASE)) {\n        let upper = grid_in[get_idx(x, y - 1u)];\n        if (can_rise(voxel, upper)) {\n            grid_out[idx] = upper;\n            return;\n        }\n    }\n\n    grid_out[idx] = voxel;\n}\n";
export const GAS_SPREAD_SHADER = "// Conservative horizontal gas spread.\n//\n// Non-air gas/plasma spreads sideways through air/gas when upward buoyancy is\n// blocked. Pair ownership is disjoint and salted to avoid one-way drift.\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE: u32 = 24u;\nconst COLD_DENSITY: u32 = 0u;\nconst GAS_RISE_THRESHOLD: i32 = 16;\noverride MOVE_PHASE: u32 = 0u;\noverride MOVE_SALT: u32 = 0u;\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }\nfn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }\n\nfn density_of(mat: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];\n}\n\nfn is_structural(ph: u32) -> bool {\n    return ph == PHASE_SOLID || ph == PHASE_FROZEN;\n}\n\nfn is_gas_like(ph: u32) -> bool {\n    return ph == PHASE_GAS || ph == PHASE_PLASMA;\n}\n\nfn gas_rank(v: u32) -> i32 {\n    return i32(get_thermal(v)) * 2 - i32(density_of(get_material(v)));\n}\n\nfn can_rise_into(src: u32, dst: u32) -> bool {\n    if (get_material(src) == MAT_AIR || !is_gas_like(get_phase(src)) || is_structural(get_phase(dst))) {\n        return false;\n    }\n    if (get_material(dst) != MAT_AIR && !is_gas_like(get_phase(dst))) {\n        return false;\n    }\n    return gas_rank(src) > gas_rank(dst) + GAS_RISE_THRESHOLD;\n}\n\nfn upward_blocked(x: u32, y: u32, src: u32) -> bool {\n    if (y == 0u) { return true; }\n    return !can_rise_into(src, grid_in[get_idx(x, y - 1u)]);\n}\n\nfn can_spread_into(src: u32, dst: u32) -> bool {\n    if (get_material(src) == MAT_AIR || !is_gas_like(get_phase(src)) || is_structural(get_phase(dst))) {\n        return false;\n    }\n    if (get_material(dst) == MAT_AIR) {\n        return true;\n    }\n    if (!is_gas_like(get_phase(dst))) {\n        return false;\n    }\n    return gas_rank(src) > gas_rank(dst) + GAS_RISE_THRESHOLD;\n}\n\nfn hash_pair(x: u32, y: u32, salt: u32) -> u32 {\n    var h = x * 374761393u + y * 668265263u + salt * 1442695041u;\n    h = (h ^ (h >> 13u)) * 1274126177u;\n    return h ^ (h >> 16u);\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n\n    var pair_left = x;\n    if (((x + MOVE_PHASE) & 1u) != 0u) {\n        if (x == 0u) {\n            grid_out[idx] = voxel;\n            return;\n        }\n        pair_left = x - 1u;\n    }\n    if (pair_left >= GRID_WIDTH - 1u) {\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    let source_left = (hash_pair(pair_left, y, MOVE_SALT) & 1u) == 0u;\n    let src_x = select(pair_left + 1u, pair_left, source_left);\n    let dst_x = select(pair_left, pair_left + 1u, source_left);\n    let src = grid_in[get_idx(src_x, y)];\n    let dst = grid_in[get_idx(dst_x, y)];\n    let do_swap = upward_blocked(src_x, y, src) && can_spread_into(src, dst);\n\n    if (do_swap && x == src_x) {\n        grid_out[idx] = dst;\n        return;\n    }\n    if (do_swap && x == dst_x) {\n        grid_out[idx] = src;\n        return;\n    }\n\n    grid_out[idx] = voxel;\n}\n";
export const THERMAL_SHADER = "// Variant: Optimized thermal diffusion with precomputed neighbor data and efficient delta accumulation\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE: u32 = 24u;\nconst COLD_CONDUCTIVITY: u32 = 1u;\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }\n\nfn set_thermal(p: u32, t: u32) -> u32 {\n    return (p & ~(THERMAL_MASK << THERMAL_SHIFT)) | ((t & THERMAL_MASK) << THERMAL_SHIFT);\n}\n\nfn conductivity_of(mat: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE + COLD_CONDUCTIVITY];\n}\n\n// Extract material and thermal in one operation\nfn get_mat_thermal(p: u32) -> vec2<u32> {\n    return vec2<u32>(get_material(p), get_thermal(p));\n}\n\n// Optimized harmonic mean using precomputed 2x value\nfn harmonic_mean_2x(a_2x: u32, b: u32) -> u32 {\n    let s = (a_2x >> 1u) + b;\n    if (s == 0u) { return 0u; }\n    return (a_2x * b) / s;\n}\n\n// Compute thermal exchange with neighbor using precomputed self_cond_2x\nfn compute_exchange(self_thermal: u32, self_cond_2x: u32, neighbor: u32) -> i32 {\n    let n_props = get_mat_thermal(neighbor);\n    let n_thermal = n_props.y;\n    let n_cond = conductivity_of(n_props.x);\n    let k = harmonic_mean_2x(self_cond_2x, n_cond);\n    return (i32(n_thermal) - i32(self_thermal)) * i32(k) / 256;\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n    \n    // Extract material and thermal together\n    let props = get_mat_thermal(voxel);\n    let self_thermal = props.y;\n    let self_cond = conductivity_of(props.x);\n    let self_cond_2x = self_cond << 1u; // Multiply by 2 using bit shift\n    \n    // Precompute neighbor indices\n    let idx_north = idx - GRID_WIDTH;\n    let idx_south = idx + GRID_WIDTH;\n    let idx_west = idx - 1u;\n    let idx_east = idx + 1u;\n    \n    // Accumulate thermal exchange\n    var delta: i32 = 0;\n    \n    // North\n    if (y > 0u) {\n        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx_north]);\n    }\n    \n    // South\n    if (y < GRID_HEIGHT - 1u) {\n        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx_south]);\n    }\n    \n    // West\n    if (x > 0u) {\n        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx_west]);\n    }\n    \n    // East\n    if (x < GRID_WIDTH - 1u) {\n        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx_east]);\n    }\n\n    // Source materials (fire, lava) radiate heat but don't cool.\n    // They emit to neighbors (neighbors compute positive delta from us),\n    // but we skip the self-subtraction. Energy is added to the system —\n    // physically correct for ongoing chemical/geological energy input.\n    // Fire lifetime is gated by fuel exhaustion (2d), not thermal budget.\n    let mat = props.x;\n    if (mat == MAT_FIRE || mat == MAT_LAVA) {\n        grid_out[idx] = voxel;  // thermal unchanged\n        return;\n    }\n\n    // Apply delta with saturating arithmetic\n    let new_thermal = i32(self_thermal) + delta;\n    let clamped = u32(max(0, min(255, new_thermal)));\n    grid_out[idx] = set_thermal(voxel, clamped);\n}";
export const PHASE_SHADER = "// Hybrid approach: bitfield construction with simplified priority resolution and fast paths\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE_L: u32 = 24u;\n\nfn ct(mat: u32, field: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE_L + field];\n}\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }\nfn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }\n\nfn rewrite_voxel(packed: u32, new_mat: u32, new_thermal: u32, new_phase: u32) -> u32 {\n    let keep = packed & 0xF0FF0000u;\n    return (new_mat & MATERIAL_MASK)\n         | ((new_thermal & THERMAL_MASK) << THERMAL_SHIFT)\n         | keep\n         | ((new_phase & PHASE_MASK) << PHASE_SHIFT);\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n    let mat = get_material(voxel);\n    let thermal = get_thermal(voxel);\n\n    if (mat == MAT_AIR || mat == MAT_FIRE) {\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    // Load all transition parameters\n    let melt_point     = ct(mat, 2u);\n    let boil_point     = ct(mat, 3u);\n    let freeze_point   = ct(mat, 8u);\n    let condense_point = ct(mat, 9u);\n    let lh_melt        = ct(mat, 10u);\n    let lh_boil        = ct(mat, 11u);\n    let melts_into     = ct(mat, 12u);\n    let boils_into     = ct(mat, 13u);\n    let freezes_into   = ct(mat, 14u);\n    let condenses_into = ct(mat, 15u);\n\n    // Build transition bitfield with priority pre-encoded\n    // Use bits 0-3 for priority order: boil=3, melt=2, freeze=1, condense=0\n    let boil_mask = select(0u, 8u, boils_into != 0u && boil_point != 0u && thermal > boil_point);\n    let melt_mask = select(0u, 4u, melts_into != 0u && melt_point != 0u && thermal > melt_point);\n    let freeze_mask = select(0u, 2u, freezes_into != 0u && freeze_point != 0u && thermal < freeze_point);\n    let condense_mask = select(0u, 1u, condenses_into != 0u && condense_point != 0u && thermal < condense_point);\n    \n    let transitions = boil_mask | melt_mask | freeze_mask | condense_mask;\n    \n    if (transitions == 0u) {\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    // Find highest set bit (highest priority transition)\n    let winner = 31u - countLeadingZeros(transitions);\n    \n    // Direct indexing into material array using winner bit\n    let material_array = array<u32, 4>(condenses_into, freezes_into, melts_into, boils_into);\n    let new_mat = material_array[winner];\n    \n    // Compute thermal change (only for melt/boil which are bits 2-3)\n    let needs_latent = winner >> 1u;  // 1 if melt or boil\n    let latent_array = array<u32, 2>(lh_melt, lh_boil);\n    let thermal_cost = latent_array[winner - 2u] * needs_latent;\n    let new_thermal = select(thermal, select(0u, thermal - thermal_cost, thermal >= thermal_cost), needs_latent != 0u);\n    \n    // Compute phase using lookup\n    let phase_array = array<u32, 4>(PHASE_LIQUID, PHASE_FROZEN, PHASE_LIQUID, PHASE_GAS);\n    let new_phase = phase_array[winner];\n\n    grid_out[idx] = rewrite_voxel(voxel, new_mat, new_thermal, new_phase);\n}";
export const COMBUSTION_SHADER = "// Variant: Vectorized combustion with fused conditions and minimal branching\n// Uses vec4 operations for parallel neighbor processing, bitwise condition fusion,\n// and optimized memory access patterns to minimize instruction count.\n\n@group(0) @binding(0) var<storage, read> grid_in: array<u32>;\n@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;\n@group(0) @binding(2) var<storage, read> cold_table: array<u32>;\n\nconst COLD_STRIDE_L: u32 = 24u;\n\nfn ct(mat: u32, field: u32) -> u32 {\n    return cold_table[mat * COLD_STRIDE_L + field];\n}\n\nfn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }\nfn get_material(p: u32) -> u32 { return p & MATERIAL_MASK; }\nfn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }\n\nfn rewrite_voxel(packed: u32, new_mat: u32, new_thermal: u32, new_phase: u32) -> u32 {\n    return new_mat | (new_thermal << THERMAL_SHIFT) | (packed & 0xF0FF0000u) | (new_phase << PHASE_SHIFT);\n}\n\nfn is_valid_dir(x: u32, y: u32, dir: u32) -> bool {\n    if (dir == 0u) { return x > 0u; }\n    if (dir == 1u) { return x < GRID_WIDTH - 1u; }\n    if (dir == 2u) { return y > 0u; }\n    return y < GRID_HEIGHT - 1u;\n}\n\nfn dir_x(x: u32, dir: u32) -> u32 {\n    if (dir == 0u) { return x - 1u; }\n    if (dir == 1u) { return x + 1u; }\n    return x;\n}\n\nfn dir_y(y: u32, dir: u32) -> u32 {\n    if (dir == 2u) { return y - 1u; }\n    if (dir == 3u) { return y + 1u; }\n    return y;\n}\n\nfn opposite_dir(dir: u32) -> u32 {\n    if (dir == 0u) { return 1u; }\n    if (dir == 1u) { return 0u; }\n    if (dir == 2u) { return 3u; }\n    return 2u;\n}\n\nfn priority_dir(slot: u32, parity: u32) -> u32 {\n    if (parity == 0u) {\n        if (slot == 0u) { return 2u; }\n        if (slot == 1u) { return 1u; }\n        if (slot == 2u) { return 3u; }\n        return 0u;\n    }\n    if (slot == 0u) { return 0u; }\n    if (slot == 1u) { return 2u; }\n    if (slot == 2u) { return 1u; }\n    return 3u;\n}\n\nfn is_burning_fuel(voxel: u32) -> bool {\n    let mat = get_material(voxel);\n    let fuel = ct(mat, 16u);\n    if (fuel == 0u) { return false; }\n    return get_thermal(voxel) > ct(mat, 4u);\n}\n\nfn chosen_air_dir_for_fuel(x: u32, y: u32) -> u32 {\n    let parity = (x + y) & 1u;\n    for (var i = 0u; i < 4u; i++) {\n        let dir = priority_dir(i, parity);\n        if (!is_valid_dir(x, y, dir)) { continue; }\n        let n = grid_in[get_idx(dir_x(x, dir), dir_y(y, dir))];\n        if (get_material(n) == MAT_AIR) { return dir; }\n    }\n    return 4u;\n}\n\nfn chosen_fuel_dir_for_air(x: u32, y: u32) -> u32 {\n    let parity = (x + y) & 1u;\n    for (var i = 0u; i < 4u; i++) {\n        let dir = priority_dir(i, parity);\n        if (!is_valid_dir(x, y, dir)) { continue; }\n\n        let fx = dir_x(x, dir);\n        let fy = dir_y(y, dir);\n        let fuel_voxel = grid_in[get_idx(fx, fy)];\n        if (!is_burning_fuel(fuel_voxel)) { continue; }\n\n        let fuel_air_dir = chosen_air_dir_for_fuel(fx, fy);\n        if (fuel_air_dir != 4u && opposite_dir(fuel_air_dir) == dir) {\n            return dir;\n        }\n    }\n    return 4u;\n}\n\n@compute @workgroup_size(16, 16)\nfn tick(@builtin(global_invocation_id) gid: vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }\n\n    let idx = get_idx(x, y);\n    let voxel = grid_in[idx];\n    let mat = get_material(voxel);\n    let thermal = get_thermal(voxel);\n\n    // === Fuel voxel burns ===\n    let fuel_energy = ct(mat, 16u);\n    \n    if (fuel_energy > 0u) {\n        let flash_point = ct(mat, 4u);\n        if (thermal > flash_point) {\n            let air_dir = chosen_air_dir_for_fuel(x, y);\n            if (air_dir != 4u) {\n                let ax = dir_x(x, air_dir);\n                let ay = dir_y(y, air_dir);\n                let air_fuel_dir = chosen_fuel_dir_for_air(ax, ay);\n                if (air_fuel_dir == opposite_dir(air_dir)) {\n                    let burns_into = ct(mat, 17u);\n                    let new_thermal = min(thermal + (fuel_energy >> 1u), 255u);\n                    // Ash gets PHASE_POWDER so gravity pulls it down, exposing fresh wood\n                    grid_out[idx] = rewrite_voxel(voxel, burns_into, new_thermal, PHASE_POWDER);\n                    return;\n                }\n            }\n        }\n    }\n\n    // === Ash consumed by adjacent fire → smoke ===\n    // Ash is loose powder; fire blows through it. Without this rule, ash\n    // crusts around wood and insulates it, stopping the burn prematurely.\n    if (mat == MAT_ASH) {\n        var fire_near = false;\n        if (x > 0u && get_material(grid_in[get_idx(x - 1u, y)]) == MAT_FIRE) { fire_near = true; }\n        if (x < GRID_WIDTH - 1u && get_material(grid_in[get_idx(x + 1u, y)]) == MAT_FIRE) { fire_near = true; }\n        if (y > 0u && get_material(grid_in[get_idx(x, y - 1u)]) == MAT_FIRE) { fire_near = true; }\n        if (y < GRID_HEIGHT - 1u && get_material(grid_in[get_idx(x, y + 1u)]) == MAT_FIRE) { fire_near = true; }\n\n        if (fire_near) {\n            // Ash blown away by fire → becomes smoke (gas, rises and disperses)\n            grid_out[idx] = rewrite_voxel(voxel, MAT_SMOKE, thermal, PHASE_GAS);\n            return;\n        }\n    }\n\n    // === Fire interactions ===\n    if (mat == MAT_FIRE) {\n        // Water extinguishes fire: fire adjacent to water → steam\n        // Water absorbs the heat. Fire can't burn when cooled by water.\n        var has_water = false;\n        if (x > 0u && get_material(grid_in[get_idx(x - 1u, y)]) == MAT_WATER) { has_water = true; }\n        if (x < GRID_WIDTH - 1u && get_material(grid_in[get_idx(x + 1u, y)]) == MAT_WATER) { has_water = true; }\n        if (y > 0u && get_material(grid_in[get_idx(x, y - 1u)]) == MAT_WATER) { has_water = true; }\n        if (y < GRID_HEIGHT - 1u && get_material(grid_in[get_idx(x, y + 1u)]) == MAT_WATER) { has_water = true; }\n\n        if (has_water) {\n            // Fire extinguished by water → becomes steam\n            grid_out[idx] = rewrite_voxel(voxel, MAT_STEAM, 100u, PHASE_GAS);\n            return;\n        }\n\n        // Fire decay: fire with no adjacent fuel → smoke\n        var has_fuel = false;\n        if (x > 0u) { let n = ct(get_material(grid_in[get_idx(x - 1u, y)]), 16u); if (n > 0u) { has_fuel = true; } }\n        if (x < GRID_WIDTH - 1u) { let n = ct(get_material(grid_in[get_idx(x + 1u, y)]), 16u); if (n > 0u) { has_fuel = true; } }\n        if (y > 0u) { let n = ct(get_material(grid_in[get_idx(x, y - 1u)]), 16u); if (n > 0u) { has_fuel = true; } }\n        if (y < GRID_HEIGHT - 1u) { let n = ct(get_material(grid_in[get_idx(x, y + 1u)]), 16u); if (n > 0u) { has_fuel = true; } }\n\n        if (!has_fuel) {\n            grid_out[idx] = rewrite_voxel(voxel, MAT_SMOKE, thermal, PHASE_GAS);\n            return;\n        }\n        // Fire with adjacent fuel persists (thermal kernel keeps it hot)\n        grid_out[idx] = voxel;\n        return;\n    }\n\n    // === Air consumed by adjacent burning fuel ===\n    if (mat == MAT_AIR) {\n        let fuel_dir = chosen_fuel_dir_for_air(x, y);\n        if (fuel_dir != 4u) {\n            let n_voxel = grid_in[get_idx(dir_x(x, fuel_dir), dir_y(y, fuel_dir))];\n            let n_mat = get_material(n_voxel);\n            let n_fuel = ct(n_mat, 16u);\n            let combustion_product = ct(n_mat, 18u);\n            if (combustion_product > 0u) {\n                // If product is fire, born at max thermal (it's the flame)\n                // If product is smoke/other, absorb fuel heat\n                var new_thermal = min(thermal + (n_fuel >> 1u), 255u);\n                if (combustion_product == MAT_FIRE) { new_thermal = 255u; }\n                grid_out[idx] = rewrite_voxel(voxel, combustion_product, new_thermal, PHASE_GAS);\n                return;\n            }\n        }\n    }\n\n    grid_out[idx] = voxel;\n}\n";
export const RENDER_SHADER = "// Phase 3a: Fragment shader — Noita-inspired rendering\n// Material ID → base color with per-voxel variation\n// Thermal → heat glow (orange/white for hot voxels)\n// Position hash → color variation (breaks flat-block look)\n// Air → subtle gradient atmosphere instead of void\n\nstruct VertexOutput {\n    @builtin(position) pos: vec4<f32>,\n    @location(0) uv: vec2<f32>,\n}\n\n@vertex\nfn vs_main(@builtin(vertex_index) vi: u32) -> VertexOutput {\n    let x = f32(vi & 1u) * 2.0 - 1.0;\n    let y = f32((vi >> 1u) & 1u) * 2.0 - 1.0;\n    var out: VertexOutput;\n    out.pos = vec4<f32>(x, -y, 0.0, 1.0);\n    out.uv = vec2<f32>(f32(vi & 1u), f32((vi >> 1u) & 1u));\n    return out;\n}\n\n@group(0) @binding(0) var<storage, read> grid: array<u32>;\n@group(0) @binding(1) var<uniform> params: vec4<u32>;\n\n// Deterministic hash for per-voxel color variation\nfn hash_pos(x: u32, y: u32) -> f32 {\n    var h = x * 374761393u + y * 668265263u;\n    h = (h ^ (h >> 13u)) * 1274126177u;\n    h = h ^ (h >> 16u);\n    return f32(h & 0xFFFFu) / 65535.0;  // 0.0 to 1.0\n}\n\nfn material_color(mat_id: u32) -> vec3<f32> {\n    switch(mat_id) {\n        case 0u:  { return vec3<f32>(0.06, 0.06, 0.10); }  // air\n        case 1u:  { return vec3<f32>(0.45, 0.43, 0.42); }  // stone\n        case 2u:  { return vec3<f32>(0.12, 0.32, 0.75); }  // water\n        case 3u:  { return vec3<f32>(0.78, 0.72, 0.48); }  // sand\n        case 4u:  { return vec3<f32>(1.00, 0.45, 0.05); }  // fire\n        case 5u:  { return vec3<f32>(0.68, 0.70, 0.73); }  // metal\n        case 6u:  { return vec3<f32>(0.18, 0.10, 0.04); }  // oil\n        case 7u:  { return vec3<f32>(0.52, 0.33, 0.14); }  // wood\n        case 8u:  { return vec3<f32>(0.72, 0.88, 0.94); }  // ice\n        case 9u:  { return vec3<f32>(0.82, 0.82, 0.86); }  // steam\n        case 10u: { return vec3<f32>(1.00, 0.28, 0.00); }  // lava\n        case 11u: { return vec3<f32>(0.65, 0.82, 0.88); }  // glass\n        case 12u: { return vec3<f32>(0.20, 0.78, 0.38); }  // player\n        case 13u: { return vec3<f32>(0.28, 0.26, 0.24); }  // ash\n        case 14u: { return vec3<f32>(0.38, 0.38, 0.40); }  // smoke\n        default:  { return vec3<f32>(1.00, 0.00, 1.00); }  // unknown\n    }\n}\n\n// How much color variation each material gets (0 = flat, 0.15 = noisy)\nfn material_variation(mat_id: u32) -> f32 {\n    switch(mat_id) {\n        case 0u:  { return 0.02; }  // air: very subtle\n        case 1u:  { return 0.12; }  // stone: noticeable grain\n        case 2u:  { return 0.06; }  // water: gentle shimmer\n        case 3u:  { return 0.10; }  // sand: grainy\n        case 4u:  { return 0.15; }  // fire: flickering\n        case 5u:  { return 0.04; }  // metal: polished\n        case 6u:  { return 0.05; }  // oil: slight sheen\n        case 7u:  { return 0.08; }  // wood: grain pattern\n        case 8u:  { return 0.04; }  // ice: crystalline\n        case 9u:  { return 0.10; }  // steam: wispy\n        case 10u: { return 0.12; }  // lava: churning\n        case 11u: { return 0.03; }  // glass: smooth\n        case 13u: { return 0.06; }  // ash: dusty\n        case 14u: { return 0.08; }  // smoke: hazy\n        default:  { return 0.05; }\n    }\n}\n\n@fragment\nfn fs_main(in: VertexOutput) -> @location(0) vec4<f32> {\n    let width = params.x;\n    let height = params.y;\n\n    let gx = u32(in.uv.x * f32(width));\n    let gy = u32(in.uv.y * f32(height));\n\n    if (gx >= width || gy >= height) {\n        return vec4<f32>(0.0, 0.0, 0.0, 1.0);\n    }\n\n    let idx = gy * width + gx;\n    let voxel = grid[idx];\n\n    let mat_id = voxel & 0xFFu;\n    let thermal = (voxel >> 8u) & 0xFFu;\n    let phase = (voxel >> 24u) & 0xFu;\n    let flags = (voxel >> 28u) & 0xFu;\n\n    // === AIR: subtle depth gradient ===\n    if (mat_id == 0u) {\n        let depth = f32(gy) / f32(height);\n        // Sky gradient: darker at top, slightly warmer at bottom (ground reflection)\n        let sky = mix(\n            vec3<f32>(0.03, 0.03, 0.08),  // deep space at top\n            vec3<f32>(0.08, 0.07, 0.10),  // ground glow at bottom\n            depth\n        );\n        // Subtle noise to prevent banding\n        let noise = (hash_pos(gx, gy) - 0.5) * 0.01;\n        return vec4<f32>(sky + noise, 1.0);\n    }\n\n    // === BASE COLOR with per-voxel variation ===\n    var color = material_color(mat_id);\n    let variation = material_variation(mat_id);\n    let noise = hash_pos(gx, gy);\n    // Vary brightness and hue slightly\n    let bright_var = 1.0 + (noise - 0.5) * variation * 2.0;\n    // Second hash for hue shift\n    let noise2 = hash_pos(gx + 1000u, gy + 1000u);\n    let hue_shift = (noise2 - 0.5) * variation * 0.3;\n    color = color * bright_var + vec3<f32>(hue_shift, -hue_shift * 0.5, hue_shift * 0.3);\n\n    // === THERMAL GLOW ===\n    let heat = f32(thermal) / 255.0;\n\n    // Low heat: subtle warm tint (above ambient ~20/255 = 0.08)\n    if (heat > 0.15) {\n        let warmth = (heat - 0.15) / 0.85;\n        // Warm: red-orange at moderate heat, white-yellow at extreme\n        let warm_color = mix(\n            vec3<f32>(0.8, 0.2, 0.0),   // deep red (moderate)\n            vec3<f32>(1.0, 0.9, 0.5),   // white-yellow (extreme)\n            warmth\n        );\n        color = mix(color, warm_color, warmth * 0.6);\n    }\n\n    // Very hot: additive glow (emissive, above 0.7)\n    if (heat > 0.7) {\n        let glow = (heat - 0.7) / 0.3;\n        let emissive = vec3<f32>(1.0, 0.6, 0.15) * glow * 0.4;\n        color = color + emissive;\n    }\n\n    // === PHASE-SPECIFIC EFFECTS ===\n\n    // Burning: flickering ember overlay\n    if (phase == 8u || (flags & 1u) != 0u) {\n        let flicker = hash_pos(gx ^ thermal, gy ^ thermal);\n        color = mix(color, vec3<f32>(1.0, 0.3, 0.0), 0.5 + flicker * 0.3);\n    }\n\n    // Liquid: slight transparency effect (darken slightly)\n    if (phase == 2u || phase == 3u) {\n        let liquid_depth = hash_pos(gx, gy + 500u) * 0.1;\n        color = color * (0.92 + liquid_depth);\n    }\n\n    // Gas/steam: semi-transparent feel (lighten toward air color)\n    if (phase == 4u && mat_id != 0u) {\n        color = mix(color, vec3<f32>(0.06, 0.06, 0.10), 0.3);\n    }\n\n    // Clamp to valid range\n    color = clamp(color, vec3<f32>(0.0), vec3<f32>(1.0));\n\n    return vec4<f32>(color, 1.0);\n}\n";
